class Solution {
public:
    bool sequenceReconstruction(vector<int>& nums, vector<vector<int>>& sequences) {
        unordered_map<int, unordered_set<int>> graph;
        unordered_map<int, int> indegree;
        for (int x : nums) indegree[x] = 0;
        for (const auto& seq : sequences) {
            for (size_t i = 0; i + 1 < seq.size(); ++i) {
                int u = seq[i], v = seq[i + 1];
                if (indegree.count(u) && indegree.count(v) && !graph[u].count(v)) {
                    graph[u].insert(v);
                    indegree[v]++;
                }
            }
        }
        queue<int> q;
        for (const auto& p : indegree) {
            if (p.second == 0) q.push(p.first);
        }
        size_t idx = 0;
        while (!q.empty()) {
            if (q.size() > 1) return false;
            int curr = q.front(); q.pop();
            if (curr != nums[idx++]) return false;
            for (int neighbor : graph[curr]) {
                if (--indegree[neighbor] == 0) {
                    q.push(neighbor);
                }
            }
        }
        return idx == nums.size();
    }
};

class Solution {
    public boolean sequenceReconstruction(int[] nums, List<List<Integer>> sequences) {
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> indegree = new HashMap<>();
        for (int x : nums) indegree.put(x, 0);
        for (List<Integer> seq : sequences) {
            for (int i = 0; i < seq.size() - 1; i++) {
                int u = seq.get(i), v = seq.get(i + 1);
                if (indegree.containsKey(u) && indegree.containsKey(v)) {
                    graph.computeIfAbsent(u, k -> new HashSet<>());
                    if (graph.get(u).add(v)) {
                        indegree.put(v, indegree.get(v) + 1);
                    }
                }
            }
        }
        Queue<Integer> q = new LinkedList<>();
        for (Map.Entry<Integer, Integer> entry : indegree.entrySet()) {
            if (entry.getValue() == 0) q.offer(entry.getKey());
        }
        int idx = 0;
        while (!q.isEmpty()) {
            if (q.size() > 1) return false;
            int curr = q.poll();
            if (curr != nums[idx++]) return false;
            if (graph.containsKey(curr)) {
                for (int neighbor : graph.get(curr)) {
                    indegree.put(neighbor, indegree.get(neighbor) - 1);
                    if (indegree.get(neighbor) == 0) q.offer(neighbor);
                }
            }
        }
        return idx == nums.length;
    }
}

