var sequenceReconstruction = function(nums, sequences) {
    const graph = new Map();
    const indegree = new Map();
    for (const x of nums) indegree.set(x, 0);
    for (const seq of sequences) {
        for (let i = 0; i < seq.length - 1; i++) {
            const u = seq[i], v = seq[i + 1];
            if (indegree.has(u) && indegree.has(v)) {
                if (!graph.has(u)) graph.set(u, new Set());
                if (!graph.get(u).has(v)) {
                    graph.get(u).add(v);
                    indegree.set(v, indegree.get(v) + 1);
                }
            }
        }
    }
    const q = [];
    for (const [x, d] of indegree) {
        if (d === 0) q.push(x);
    }
    let idx = 0;
    while (q.length > 0) {
        if (q.length > 1) return false;
        const curr = q.shift();
        if (curr !== nums[idx++]) return false;
        if (graph.has(curr)) {
            for (const neighbor of graph.get(curr)) {
                indegree.set(neighbor, indegree.get(neighbor) - 1);
                if (indegree.get(neighbor) === 0) q.push(neighbor);
            }
        }
    }
    return idx === nums.length;
};
